import * as pdfjs from './vendor/pdf.min.mjs';
pdfjs.GlobalWorkerOptions.workerSrc = new URL('./vendor/pdf.worker.min.mjs', import.meta.url).href;
const $ = (s, el=document) => el.querySelector(s);
const esc = s => String(s ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={home:'M3 10 12 3l9 7M5 9v11h5v-6h4v6h5V9',book:'M4 3h12a3 3 0 0 1 3 3v15H6a3 3 0 0 1-3-3V6a3 3 0 0 1 3-3M3 17h16M8 7h7M8 11h5',upload:'M12 16V3m-5 5 5-5 5 5M4 15v5h16v-5',arrow:'M5 12h14m-5-5 5 5-5 5',left:'m14 6-6 6 6 6',right:'m10 6 6 6-6 6',check:'m5 12 4 4L19 6',plus:'M12 5v14M5 12h14',close:'m6 6 12 12M18 6 6 18',file:'M14 2H5v20h14V7l-5-5v5h5M8 12h8M8 16h6',pen:'m4 16-1 5 5-1L20 8l-4-4L4 16m9-9 4 4',eraser:'m4 14 9-10a2 2 0 0 1 3 0l5 5a2 2 0 0 1 0 3l-8 9H8l-4-4a2 2 0 0 1 0-3Zm4-5 9 8M13 21h9',undo:'M9 4 3 10l6 5M3 10h11a6 6 0 0 1 0 12',redo:'m15 4 6 6-6 5M21 10H10a6 6 0 0 0 0 12',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3M20 2v4m-2-2h4',chart:'M4 20h17M7 16v-5m5 5V4m5 12V8',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',download:'M12 3v13m-5-5 5 5 5-5M4 16v5h16v-5',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',hand:'M8 12V6a2 2 0 0 1 4 0v5-7a2 2 0 0 1 4 0v7-5a2 2 0 0 1 4 0v10c0 4-3 6-7 6-3 0-5-2-7-5l-3-5a2 2 0 0 1 3-2l2 2',info:'M12 11v6M12 7h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',trash:'M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7',zoom:'M21 21l-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0M6 10h8M10 6v8',shield:'m12 2 8 3v7c0 5-8 10-8 10S4 17 4 12V5l8-3m-4 9 3 3 5-6'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.file}"/></svg>`;
const btn=(label,action,style='primary',ico='')=>`<button class="btn ${style}" data-action="${action}">${ico?icon(ico):''}${label}</button>`;
const ib=(ico,action,label,active=false)=>`<button class="icon-button ${active?'active':''}" data-action="${action}" aria-label="${label}" title="${label}">${icon(ico)}</button>`;
const safeRead=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}};
const state={route:'home',doc:null,page:1,pdf:null,bytes:null,ink:safeRead('ng-ink',{}),tool:'pen',color:'#233c34',width:2,zoom:1,filter:'all',graded:safeRead('ng-graded',false),reviewed:safeRead('ng-reviewed',false),answers:['④','③','③'],saveOk:true,documents:[],mode:'exam'};
let renderToken=0,redo=[],stroke=null,db,toastTimer,renderTask;
function store(key,val){try{localStorage.setItem(key,JSON.stringify(val));return true}catch{return false}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200)}
async function initDB(){return new Promise((resolve,reject)=>{const req=indexedDB.open('noteguard-v1',1);req.onupgradeneeded=()=>req.result.createObjectStore('documents',{keyPath:'id'});req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
async function dbAll(){if(!db)return[];return new Promise(resolve=>{const r=db.transaction('documents').objectStore('documents').getAll();r.onsuccess=()=>resolve(r.result);r.onerror=()=>resolve([])})}
async function dbPut(doc){if(!db)return false;return new Promise(resolve=>{const t=db.transaction('documents','readwrite');t.objectStore('documents').put(doc);t.oncomplete=()=>resolve(true);t.onerror=()=>resolve(false)})}
const demo={id:'demo-exam',name:'2026 9월 모의고사',fileName:'2026 9월 모의고사 · 수학.pdf',pages:20,demo:true};
const brand=()=>`<div class="brand"><div class="brand-mark">${icon('book')}</div><span>NoteGuard</span></div>`;
const navItems=[['home','home','학습 홈'],['library','file','내 모의고사'],['notebook','book','오답노트'],['insights','chart','학습 리포트']];
function shell(body,active='home'){return `<div class="shell"><aside class="sidebar">${brand()}<div class="brand-sub">WRITE. LEARN. GROW.</div><nav class="nav">${navItems.map(([r,i,l])=>`<button data-go="${r}" class="${active===r?'active':''}">${icon(i)}<span>${l}</span>${r==='notebook'&&state.graded&&!state.reviewed?'<span class="count">1</span>':''}</button>`).join('')}</nav><div class="sidebar-foot"><div class="quiet-note"><b>작은 실수가, 다음 실력이 되도록.</b>오늘의 풀이를 차곡차곡<br>쌓아보세요.</div><div class="profile"><span class="avatar">나</span><div>나의 학습 공간<small>꾸준히, 나만의 속도로</small></div></div></div></aside><main class="main"><header class="topbar"><div class="mobile-brand">${brand()}</div><div class="crumb">나의 학습 공간 ${icon('right')} <strong>${navItems.find(x=>x[0]===active)?.[2]||'모의고사 업로드'}</strong></div><div class="top-actions"><span class="dot"></span><span class="wide-only">오늘도 한 걸음</span><span class="avatar">나</span></div></header><div class="content">${body}</div></main><nav class="bottom-nav">${navItems.map(([r,i,l])=>`<button data-go="${r}" class="${active===r?'active':''}">${icon(i)}${l}</button>`).join('')}</nav></div>`}
function docCard(doc){return `<article class="document-card"><div class="document-cover"><small>MATHEMATICS</small><b>수학</b><small>${doc.demo?'2026 · 09':'MY EXAM'}</small></div><div class="document-info"><span class="badge ${doc.demo?'':'neutral'}">${doc.demo?'예시 모의고사':'내 PDF'}</span><h3>${esc(doc.name)}</h3><p>${doc.pages}페이지 · ${doc.demo?'문제지 원본 / 문항별 보기 지원':'이 기기에 저장됨'}<br>${doc.demo?'PDF 위에 직접 풀이를 작성해보세요.':esc(doc.fileName)}</p></div><div class="list-actions"><button class="btn secondary small" data-open="${doc.id}">문제 풀기 ${icon('arrow')}</button></div></article>`}
function home(){return shell(`<div class="heading"><div><div class="eyebrow">MY LEARNING SPACE</div><h1>오늘도, 한 문제 더.</h1><p class="subtitle">직접 쓰고, 돌아보고, 나의 실력으로 만들어보세요.</p></div><span class="session-chip">나만의 수학 노트</span></div><section class="hero"><div><div class="eyebrow">YOUR NEXT CHAPTER</div><h2>풀이의 시작부터<br>이해하는 순간까지.</h2><p>익숙한 문제지 위에, 나만의 풀이를.<br>모의고사를 불러와 학습을 시작해보세요.</p>${btn('모의고사 업로드','upload','primary','plus')}</div><div class="paper-art" aria-hidden="true"><div class="sheet back"></div><div class="sheet"><small style="font-size:8px;letter-spacing:1px">MY MATH NOTE</small><div class="line"></div><div class="formula">∫ f(x) dx</div><div class="line"></div><div class="line" style="width:60%"></div><div class="circle">✓</div></div></div></section><div class="stats"><div class="stat"><div><label>내 모의고사</label><strong>${state.documents.length+1}<span>개</span></strong></div>${icon('file')}</div><div class="stat"><div><label>복습할 오답</label><strong>${state.graded&&!state.reviewed?1:0}<span>문제</span></strong></div>${icon('book')}</div><div class="stat"><div><label>복습 완료</label><strong>${state.reviewed?1:0}<span>문제</span></strong></div>${icon('check')}</div></div><div class="section-head"><h2>이어서 학습하기</h2><button class="text-button" data-go="library">전체 보기 ${icon('right')}</button></div>${docCard(state.documents.at(-1)||demo)}<div class="section-head"><h2>오늘의 학습 메모</h2></div><div class="callout">${icon('spark')}<div><b>틀린 문제도 좋은 출발점이에요.</b><br>답만 고치기보다, 어느 줄에서 달라졌는지 확인해보세요.</div></div><p class="home-footer">NoteGuard · 나의 풀이가 실력이 되는 곳</p>`)}
function library(){return shell(`<div class="heading"><div><div class="eyebrow">MY EXAMS</div><h1>내 모의고사</h1><p class="subtitle">문제지는 그대로, 풀이는 자유롭게.</p></div>${btn('PDF 추가','upload','primary','plus')}</div>${[...state.documents].reverse().map(docCard).join('')}${docCard(demo)}<div class="callout">${icon('shield')}<div>업로드한 PDF와 필기는 이 브라우저에 저장돼요.<br>다른 기기에서도 보관하려면 필기한 PDF를 내려받아주세요.</div></div>`,'library')}
function upload(){return shell(`<div class="heading"><div><div class="eyebrow">NEW EXAM</div><h1>새로운 풀이를 시작해요.</h1><p class="subtitle">수학 모의고사 PDF를 불러오세요.</p></div></div><div class="steps"><div class="step active"><span>1</span>PDF 선택</div><div class="step"><span>2</span>업로드 확인</div><div class="step"><span>3</span>문제 풀기</div></div><section class="upload-zone" id="drop-zone"><div class="upload-icon">${icon('upload')}</div><h2>여기에 PDF를 놓아주세요</h2><p>또는 아래 버튼으로 파일을 선택할 수 있어요.</p>${btn('PDF 파일 선택','choose-file','primary','plus')}<input class="upload-hidden" id="pdf-input" type="file" accept="application/pdf,.pdf" aria-label="PDF 파일 선택"><small>PDF 파일 · 최대 30MB</small></section><div class="callout">${icon('info')}<div>문제지의 글자와 도형은 그대로 유지돼요.<br>불러온 PDF 위에 펜으로 직접 풀이를 작성할 수 있어요.</div></div><div class="section-head"><h2>준비된 모의고사로 먼저 시작할까요?</h2></div>${docCard(demo)}`,'library')}
function uploaded(){return shell(`<div class="success-icon">${icon('check')}</div><div class="eyebrow">READY TO WRITE</div><h1>문제지를 불러왔어요.</h1><p class="subtitle">펜을 골라, 첫 번째 풀이를 시작해보세요.</p><div style="height:28px"></div>${docCard(state.doc)}<div class="panel"><h3>이렇게 사용할 수 있어요</h3><div class="divider"></div><p class="muted">01 &nbsp; 펜 도구로 문제지 빈 공간에 풀이를 작성해요.<br><br>02 &nbsp; 페이지를 넘겨도 작성한 필기는 그대로 남아요.<br><br>03 &nbsp; 풀이가 끝나면 필기한 PDF를 저장하거나 채점 흐름을 확인해요.</p></div>${btn('문제 풀기 시작','start-editor','primary full','arrow')}`,'library')}
function result(){return shell(`<div class="heading"><div><div class="eyebrow">EXAM REVIEW</div><h1>풀이를 돌아볼 시간.</h1><p class="subtitle">맞힌 문제는 자신감으로, 틀린 문제는 다음 기회로.</p></div></div><div class="demo-notice">시연용 채점 결과예요. 실제 필기 인식·AI 채점은 연결되어 있지 않아요.</div><div class="panel score-panel"><div><div class="eyebrow">2026 9월 모의고사 · 예시 3문항</div><h2>차근차근, 잘하고 있어요.</h2><p>한 문제만 더 확인하면 돼요.<br>틀린 문제는 오답노트에 저장했어요.</p></div><div class="score-ring"><div><strong>2<span style="font-size:16px;color:#a8c1b2"> / 3</span></strong><small>정답 문항</small></div></div></div><div class="panel"><div class="section-head" style="margin-top:0"><h2>문항별 결과</h2><span class="badge neutral">예시 답안</span></div><table class="result-table"><thead><tr><th>문항</th><th>작성한 답</th><th>정답</th><th>결과</th></tr></thead><tbody><tr><td>1번</td><td>④</td><td>④</td><td class="correct">○ 정답</td></tr><tr><td>2번</td><td>③</td><td>③</td><td class="correct">○ 정답</td></tr><tr><td>5번</td><td>③</td><td>①</td><td class="wrong">× 오답</td></tr></tbody></table></div><div class="review-buttons">${btn('오답노트 확인','notebook','primary','book')}${btn('문제지로 돌아가기','return-editor','secondary')}</div>`,'library')}
function notebook(){let show=state.graded&&(state.filter==='all'||(state.filter==='done'?state.reviewed:!state.reviewed));return shell(`<div class="heading"><div><div class="eyebrow">MY REVIEW NOTES</div><h1>다시 보면, 내 것이 되니까.</h1><p class="subtitle">나의 실수를 모아, 다음 풀이의 힌트로.</p></div><span class="badge neutral">${state.graded?1:0}문제</span></div><div class="tabs">${[['all','전체'],['todo','복습할 문제'],['done','복습 완료']].map(([id,label])=>`<button data-filter="${id}" class="${state.filter===id?'active':''}">${label}</button>`).join('')}</div>${show?`<article class="wrong-card"><div class="row"><span class="badge ${state.reviewed?'':'warm'}">${state.reviewed?'복습 완료':'복습이 필요해요'}</span><span class="muted">2026 9월 모의고사</span></div><h3>5번 문제</h3><p class="muted">정적분 계산 · 계산 과정 점검</p><div class="question-preview"><img src="assets/q5.webp" alt="모의고사 5번 정적분 문제"></div><div class="row"><span class="muted">내 답 <b class="wrong">③</b> &nbsp; → &nbsp; 정답 <b class="correct">①</b></span>${btn('오답 살펴보기','detail','primary small','arrow')}</div></article>`:`<div class="panel empty">${icon('book')}<h2>${state.graded?'이 목록은 아직 비어 있어요.':'오답노트를 채워볼까요?'}</h2><p>${state.graded?'다른 목록에서 문제를 확인해보세요.':'문제를 풀고 채점 시연을 하면 틀린 문제가 여기에 모여요.'}</p>${btn(state.graded?'전체 보기':'모의고사 풀기',state.graded?'all-filter':'open-demo','primary')}</div>`}<div class="callout">${icon('spark')}<div>정답을 외우기보다, <b>틀린 이유를 한 줄로 정리</b>해보세요.<br>복습의 시작은 내 풀이를 이해하는 거예요.</div></div>`,'notebook')}
function detail(){return shell(`<div class="heading"><div><button class="text-button" data-go="notebook" style="margin-bottom:20px">${icon('left')} 오답노트</button><div class="eyebrow">REVIEW · QUESTION 05</div><h1>어느 부분에서 달라졌을까요?</h1><p class="subtitle">2026 9월 모의고사 · 5번 문제</p></div></div><div class="panel question-panel"><div class="row"><span class="badge warm">정적분 계산</span><span class="muted">내 답 <b class="wrong">③</b> → 정답 <b class="correct">①</b></span></div><img src="assets/q5.webp" alt="5번 문제" style="margin-top:20px"><div class="divider"></div><div class="row"><p class="muted">원래 풀이와 비교하면서 확인해보세요.</p>${btn('내 풀이 보기','review-original','secondary small')}</div></div><div class="panel"><div class="feedback-heading"><span class="ai-mark">${icon('spark')}</span><h2>AI 오답 피드백</h2><span class="badge neutral">예시</span></div><p class="subtitle">계산 과정에서 놓친 부분과 관련 개념을 함께 확인해요.</p><div style="margin-top:22px">${btn('피드백 확인하기','feedback','primary full','spark')}</div></div>`,'notebook')}
function feedback(){return shell(`<div class="heading"><div><button class="text-button" data-go="detail" style="margin-bottom:20px">${icon('left')} 5번 문제</button><div class="eyebrow">UNDERSTAND YOUR MISTAKE</div><h1>풀이의 마지막 한 줄까지.</h1><p class="subtitle">틀린 이유를 알면, 다음 풀이는 달라져요.</p></div></div><div class="demo-notice">아래는 5번 문항의 예시 피드백이에요. 사용자의 손글씨를 실제로 분석한 결과는 아니에요.</div><div class="panel"><div class="feedback-heading"><span class="ai-mark">${icon('spark')}</span><h2>계산 과정 점검</h2><span class="badge warm">5번 문항</span></div><div class="feedback-block"><h3>−x 항의 적분도 확인했나요?</h3><p>피적분함수의 마지막 항 −x를 적분하면 −x²/2가 돼요. 부호를 바꾸거나 이 항을 빠뜨리면 답이 달라져요. 항마다 적분한 뒤, 원시함수를 한 번 미분해 원래 식과 같은지 확인해보세요.</p></div><div class="feedback-block"><h3>위끝값 − 아래끝값, 순서대로</h3><p>정적분에서는 F(2)만 계산하는 것이 아니라 F(2) − F(0)을 구해야 해요. 아래끝값을 대입한 식 전체에 괄호를 써두면 부호 실수를 줄일 수 있어요.</p><div class="formula-box">∫₀² (2x³ + 6x² − x) dx<br>= [ x⁴/2 + 2x³ − x²/2 ]₀²<br>= (8 + 16 − 2) − 0 = <strong>22</strong></div></div><div class="callout">${icon('check')}<div><b>다음 풀이에서 기억할 한 가지</b><br>적분 → 양 끝값 대입 → 괄호로 묶어 빼기 → 검산</div></div></div><div class="panel"><h3>관련 개념 · 정적분의 계산</h3><p class="subtitle">F′(x) = f(x)일 때, ∫ₐᵇ f(x) dx = F(b) − F(a)</p></div>${btn('유사 문제로 다시 풀어보기','similar-intro','primary full','arrow')}`,'notebook')}
function similarIntro(){return shell(`<div class="eyebrow">ONE MORE TRY</div><h1>이번에는, 스스로 풀어봐요.</h1><p class="subtitle">방금 확인한 개념을 새로운 문제에 적용해보세요.</p><div style="height:25px"></div><div class="panel"><div class="row"><span class="badge">5번 문항 복습</span><span class="badge neutral">추천 예시</span></div><h2 style="margin:22px 0 10px">한 번 더 확인하는 정적분</h2><p class="muted">양 끝값을 대입할 때, 괄호와 부호에 집중해보세요.</p><div class="divider"></div><div class="formula-box">∫₁² (3x² − 2x + 1) dx의 값을 구하시오.</div><p class="muted" style="margin-top:20px">빈 공간에 직접 풀이를 쓰고, 최종 답을 확인할 수 있어요.</p></div>${btn('직접 풀어보기','start-similar','primary full','pen')}`,'notebook')}
function reviewDone(){return shell(`<div class="success-icon">${icon('check')}</div><div class="eyebrow">A LITTLE MORE CONFIDENT</div><h1>한 걸음 더, 내 실력으로.</h1><p class="subtitle">5번 문제의 복습을 완료했어요.</p><div style="height:26px"></div><div class="panel"><span class="badge">복습 완료</span><h2 style="margin:18px 0 12px">양 끝값을 빠짐없이 확인했어요.</h2><p class="muted">다음에도 F(b) − F(a)의 순서와 괄호를 기억해보세요.</p><div class="formula-box">[ x³ − x² + x ]₁² = 6 − 1 = 5</div></div><div class="review-buttons">${btn('오답노트로 돌아가기','notebook','primary','book')}${btn('학습 홈','home','secondary')}</div>`,'notebook')}
function insights(){return shell(`<div class="heading"><div><div class="eyebrow">LEARNING REFLECTION</div><h1>나의 풀이를 이해하는 시간.</h1><p class="subtitle">어디에서 멈췄는지 알면, 다음 방향이 보여요.</p></div></div>${state.graded?`<div class="demo-notice">시연용 3문항을 기준으로 한 예시 리포트예요. 실제 학습 성향을 분석한 결과는 아니에요.</div><div class="stats"><div class="stat"><div><label>확인한 문항</label><strong>3<span>문제</span></strong></div></div><div class="stat"><div><label>다시 볼 문항</label><strong>${state.reviewed?0:1}<span>문제</span></strong></div></div><div class="stat"><div><label>복습 완료</label><strong>${state.reviewed?1:0}<span>문제</span></strong></div></div></div><div class="panel"><h2>이번 풀이에서 확인할 부분</h2><div class="insight"><span class="insight-number">01</span><div><h3>정적분 계산을 끝까지 점검해요.</h3><p>−x 항의 적분과 아래끝값 대입을 빠뜨리지 않았는지 확인해보세요.</p><button class="badge warm" data-go="feedback">관련 문항 · 5번 ${icon('right')}</button></div></div><div class="insight"><span class="insight-number">02</span><div><h3>검산을 작은 습관으로.</h3><p>원시함수를 미분해 원래 식으로 돌아오는지 확인하면 적분 과정의 실수를 발견할 수 있어요.</p></div></div></div>${btn('오답 복습 이어가기','notebook','primary','arrow')}`:`<div class="panel empty">${icon('chart')}<h2>학습 기록이 쌓이면 시작돼요.</h2><p>모의고사를 풀고 채점 시연을 먼저 확인해보세요.</p>${btn('모의고사 풀기','open-demo','primary')}</div>`}`,'insights')}
function editor(){const similar=state.mode==='similar';return `<div class="shell editor-layout"><aside class="sidebar">${brand()}<nav class="nav">${navItems.map(([r,i,l])=>`<button data-go="${r}" title="${l}" aria-label="${l}">${icon(i)}</button>`).join('')}</nav></aside><main class="main"><header class="editor-head"><div class="row" style="gap:9px">${ib('left',similar?'similar-intro':'library','목록으로')}<div class="editor-title"><h2>${similar?'유사 문제 풀기':esc(state.doc?.name||demo.name)}</h2><p>${similar?'문제 위에 자유롭게 풀이를 작성하세요.':'나의 풀이 · PDF 위에 바로 필기'}</p></div></div><div class="row" style="gap:7px">${!similar?btn('PDF 저장','export','secondary small','download'):''}${btn(similar?'답 확인':'채점하기',similar?'check-similar':'grade','primary small',similar?'check':'spark')}</div></header><div class="toolbar" role="toolbar" aria-label="필기 도구">${ib('pen','tool-pen','펜',state.tool==='pen')}${ib('eraser','tool-eraser','획 지우개',state.tool==='eraser')}${ib('hand','tool-hand','손 도구 · 스크롤',state.tool==='hand')}<div class="tool-sep"></div>${['#233c34','#2375b7','#c95848'].map(c=>`<button class="color-button ${state.color===c?'active':''}" style="--color:${c}" data-color="${c}" aria-label="${c==='#233c34'?'검정':c==='#2375b7'?'파랑':'빨강'} 펜" title="펜 색"></button>`).join('')}<select id="pen-width" aria-label="펜 굵기">${[[1.3,'얇게'],[2,'보통'],[3.5,'굵게']].map(([v,l])=>`<option value="${v}" ${state.width===v?'selected':''}>${l}</option>`).join('')}</select><div class="tool-sep"></div>${ib('undo','undo','실행 취소')}${ib('redo','redo','다시 실행')}<select id="zoom" aria-label="확대 비율">${[[1,'맞춤'],[1.25,'125%'],[1.5,'150%'],[2,'200%']].map(([v,l])=>`<option value="${v}" ${state.zoom===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="editor-scroll" id="editor-scroll"><div class="loading"><span class="spinner"></span>문제지를 불러오고 있어요.</div></div><footer class="editor-footer"><span class="saved" id="save-label">${icon('check')} 이 기기에 저장</span>${similar?'<span class="muted">복습 문제 · 1 / 1</span>':`<div class="pager">${ib('left','prev-page','이전 페이지')}<select id="page-select" aria-label="페이지 선택">${Array.from({length:state.pdf?.numPages||1},(_,i)=>`<option value="${i+1}" ${state.page===i+1?'selected':''}>${i+1}</option>`).join('')}</select><span>/ ${state.pdf?.numPages||1}</span>${ib('right','next-page','다음 페이지')}</div>`}${state.doc?.demo&&!similar?`<button class="btn secondary small" data-action="switch-mode">${state.mode==='exam'?'문항별 보기':'원본 보기'}</button>`:'<span class="muted">직접 필기</span>'}</footer></main></div>`}
const screens={home,library,upload,uploaded,result,notebook,detail,feedback,'similar-intro':similarIntro,'review-done':reviewDone,insights,editor};
function go(route){renderToken++;renderTask?.cancel();state.route=route;$('#app').innerHTML=(screens[route]||home)();window.scrollTo(0,0);if(route==='editor')drawPage();if(route==='upload')setupUpload();history.replaceState(null,'','#'+route)}
function showModal(html){$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="안내">${html}</section></div>`;$('.modal button, .modal input')?.focus()}
function closeModal(){$('#modal-root').innerHTML=''}
async function loadDoc(doc,mode='exam',page=1){state.doc=doc;state.mode=mode;state.page=page;state.zoom=1;redo=[];$('#app').innerHTML=shell('<div class="loading"><span class="spinner"></span>문제지를 불러오고 있어요.</div>','library');try{const data=doc.demo?await(await fetch(mode==='questions'?'assets/practice.pdf':'assets/exam.pdf')).arrayBuffer():doc.data;state.bytes=data.slice(0);state.pdf=await pdfjs.getDocument({data:new Uint8Array(data.slice(0))}).promise;go('editor')}catch(e){go('library');toast('PDF를 열지 못했어요. 파일이 정상인지 확인해주세요.');console.error(e)}}
function inkKey(){return state.mode==='similar'?'similar-v1':`${state.doc.id}-${state.mode}-${state.page}`}
function currentInk(){return state.ink[inkKey()]||[]}
function saveInk(){state.saveOk=store('ng-ink',state.ink);const l=$('#save-label');if(l)l.innerHTML=`${icon(state.saveOk?'check':'info')}${state.saveOk?'이 기기에 저장됨':'저장 공간 부족 · PDF로 저장'}`}
function drawStroke(ctx,s,w,h){if(!s.points.length)return;ctx.strokeStyle=s.color;ctx.fillStyle=s.color;ctx.lineWidth=s.width*w/800;ctx.lineCap='round';ctx.lineJoin='round';if(s.points.length===1){const p=s.points[0];ctx.beginPath();ctx.arc(p.x*w,p.y*h,ctx.lineWidth/2,0,Math.PI*2);ctx.fill();return}ctx.beginPath();s.points.forEach((p,i)=>i?ctx.lineTo(p.x*w,p.y*h):ctx.moveTo(p.x*w,p.y*h));ctx.stroke()}
function redrawInk(){const c=$('#ink');if(!c)return;const ctx=c.getContext('2d');ctx.clearRect(0,0,c.width,c.height);for(const s of currentInk())drawStroke(ctx,s,c.width,c.height);if(stroke)drawStroke(ctx,stroke,c.width,c.height)}
function setupInk(){const c=$('#ink');if(!c)return;c.style.pointerEvents=state.tool==='hand'?'none':'auto';c.style.cursor=state.tool==='eraser'?'cell':'crosshair';function point(e){const r=c.getBoundingClientRect();return{x:(e.clientX-r.left)/r.width,y:(e.clientY-r.top)/r.height}}let erasing=false,eraseSnapshot=null;function erase(p){const threshold=15/c.getBoundingClientRect().width;const old=currentInk();state.ink[inkKey()]=old.filter(s=>!s.points.some(q=>Math.hypot(q.x-p.x,(q.y-p.y)*c.height/c.width)<threshold));redrawInk()}
 c.onpointerdown=e=>{if(e.button!==0&&e.pointerType==='mouse')return;if(!e.isPrimary)return;e.preventDefault();c.setPointerCapture(e.pointerId);if(state.tool==='eraser'){erasing=true;eraseSnapshot=structuredClone(currentInk());erase(point(e))}else{stroke={color:state.color,width:state.width,points:[point(e)]};redrawInk()}};
 c.onpointermove=e=>{if(!c.hasPointerCapture(e.pointerId))return;e.preventDefault();if(erasing){erase(point(e));return}if(!stroke)return;const events=e.getCoalescedEvents?.();for(const ev of events?.length?events:[e])stroke.points.push(point(ev));redrawInk()};
 const finish=e=>{if(!c.hasPointerCapture(e.pointerId))return;if(stroke){const before=structuredClone(currentInk());state.ink[inkKey()]=[...currentInk(),stroke];pushUndo(before);stroke=null}else if(erasing){pushUndo(eraseSnapshot);erasing=false}c.releasePointerCapture(e.pointerId);redo=[];saveInk();redrawInk()};c.onpointerup=finish;c.onpointercancel=finish;redrawInk();}
const undoStacks={};function pushUndo(before){const key=inkKey();(undoStacks[key]??=[]).push(before);if(undoStacks[key].length>40)undoStacks[key].shift()}
async function drawPage(){const token=++renderToken;renderTask?.cancel();const host=$('#editor-scroll');if(!host)return;host.innerHTML='<div class="loading"><span class="spinner"></span>문제지를 준비하고 있어요.</div>';try{const base=Math.min(host.clientWidth-32,834);const width=Math.max(260,base)*state.zoom;let height;let wrap=document.createElement('div');wrap.className='paper-wrap';wrap.style.width=width+'px';if(state.mode==='similar'){height=width*1.414;wrap.innerHTML=`<canvas id="pdf-canvas" class="pdf"></canvas><canvas class="ink" id="ink" aria-label="풀이를 직접 쓰는 공간"></canvas>`;host.replaceChildren(wrap);const c=$('#pdf-canvas');c.width=width*2;c.height=height*2;const ctx=c.getContext('2d');ctx.fillStyle='white';ctx.fillRect(0,0,c.width,c.height);ctx.scale(width*2/800,width*2/800);ctx.fillStyle='#232c27';ctx.font='600 18px "Noto Sans KR",sans-serif';ctx.fillText('1. 다음 정적분의 값을 구하시오. [3점]',55,75);ctx.font='27px Georgia,serif';ctx.fillText('∫₁² (3x² − 2x + 1) dx',100,145);ctx.font='15px "Noto Sans KR",sans-serif';ctx.fillStyle='#89938b';ctx.fillText('풀이와 최종 답을 자유롭게 작성하세요.',55,215)}else{const page=await state.pdf.getPage(state.page);if(token!==renderToken)return;const natural=page.getViewport({scale:1});height=width*natural.height/natural.width;wrap.innerHTML='<canvas id="pdf-canvas" class="pdf"></canvas><canvas class="ink" id="ink" aria-label="문제지 위에 직접 쓰는 공간"></canvas>';host.replaceChildren(wrap);const c=$('#pdf-canvas');const ratio=Math.min(devicePixelRatio||1,2);const viewport=page.getViewport({scale:width/natural.width*ratio});c.width=Math.floor(viewport.width);c.height=Math.floor(viewport.height);renderTask=page.render({canvasContext:c.getContext('2d'),viewport});await renderTask.promise;if(token!==renderToken)return;}const c=$('#ink');if(!c)return;const ratio=Math.min(devicePixelRatio||1,2);c.width=Math.round(width*ratio);c.height=Math.round(height*ratio);setupInk();const prev=$('[data-action="prev-page"]'),next=$('[data-action="next-page"]');if(prev)prev.disabled=state.page===1;if(next)next.disabled=state.page===state.pdf.numPages;saveInk()}catch(e){if(e.name==='RenderingCancelledException')return;host.innerHTML='<div class="empty"><h3>페이지를 표시하지 못했어요.</h3><p>다시 열거나 다른 PDF를 선택해주세요.</p><button class="btn secondary" data-action="return-editor">다시 시도</button></div>';console.error(e)}}
function setupUpload(){const zone=$('#drop-zone'),input=$('#pdf-input');input.onchange=()=>uploadFile(input.files[0]);zone.ondragover=e=>{e.preventDefault();zone.classList.add('dragging')};zone.ondragleave=()=>zone.classList.remove('dragging');zone.ondrop=e=>{e.preventDefault();zone.classList.remove('dragging');uploadFile(e.dataTransfer.files[0])}}
async function uploadFile(file){if(!file)return;if(!/\.pdf$/i.test(file.name)&&file.type!=='application/pdf'){toast('PDF 파일을 선택해주세요.');return}if(file.size>30*1024*1024){toast('30MB 이하 PDF를 선택해주세요.');return}$('#drop-zone').innerHTML='<div class="loading" style="min-height:150px"><span class="spinner"></span>PDF를 확인하고 있어요.</div>';try{const data=await file.arrayBuffer();const doc=await pdfjs.getDocument({data:new Uint8Array(data.slice(0))}).promise;const entry={id:crypto.randomUUID(),name:file.name.replace(/\.pdf$/i,''),fileName:file.name,data,pages:doc.numPages,added:Date.now()};const saved=await dbPut(entry);state.documents.push(entry);state.doc=entry;await doc.destroy();go('uploaded');if(!saved)toast('이번 방문 동안 사용할 수 있어요. 브라우저 저장 공간을 확인해주세요.')}catch(e){go('upload');toast(e.name==='PasswordException'?'암호가 없는 PDF를 선택해주세요.':'PDF를 읽을 수 없어요. 파일을 확인해주세요.')}}
async function exportPDF(){if(!state.pdf||!state.bytes)return;const b=$('[data-action="export"]');b.disabled=true;b.textContent='저장 중…';try{const out=await PDFLib.PDFDocument.load(state.bytes.slice(0));for(let i=0;i<out.getPageCount();i++){const strokes=state.ink[`${state.doc.id}-${state.mode}-${i+1}`];if(!strokes?.length)continue;const page=out.getPage(i);const box=page.getCropBox();const rotation=((page.getRotation().angle%360)+360)%360;const viewPage=await state.pdf.getPage(i+1);const view=viewPage.getViewport({scale:1});for(const s of strokes){const hex=s.color.replace('#','');const color=PDFLib.rgb(parseInt(hex.slice(0,2),16)/255,parseInt(hex.slice(2,4),16)/255,parseInt(hex.slice(4,6),16)/255);const pts=s.points.map(p=>view.convertToPdfPoint(p.x*view.width,p.y*view.height));const thickness=s.width*view.width/800;if(pts.length===1)page.drawCircle({x:pts[0][0],y:pts[0][1],size:thickness/2,color});for(let j=1;j<pts.length;j++)page.drawLine({start:{x:pts[j-1][0],y:pts[j-1][1]},end:{x:pts[j][0],y:pts[j][1]},thickness,color});}}const bytes=await out.save();const url=URL.createObjectURL(new Blob([bytes],{type:'application/pdf'}));const a=document.createElement('a');a.href=url;a.download=state.doc.name+'-내풀이.pdf';a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);toast('필기한 PDF를 저장했어요.')}catch(e){toast('PDF 저장에 실패했어요. 다시 시도해주세요.');console.error(e)}finally{b.disabled=false;b.innerHTML=icon('download')+'PDF 저장'}}
function grade(){showModal(`<span class="badge neutral">프로토타입 시연</span><h2 style="margin-top:16px">채점 흐름을 확인할까요?</h2><p class="subtitle">실제 손글씨 인식과 AI 채점은 아직 연결되지 않았어요. 준비된 1·2·5번 문항의 예시 결과로 채점 이후 흐름을 보여드려요.</p><div class="panel" style="padding:16px;background:#f7f9f4"><div class="row"><span class="muted">예시 답안</span><b style="font-size:13px">1번 ④ · 2번 ③ · 5번 ③</b></div></div><p class="muted">${state.doc?.demo?'작성한 필기는 그대로 보관돼요.':'업로드한 PDF의 실제 채점 결과가 아니에요.'}</p><div class="modal-actions">${btn('계속 풀기','close-modal','secondary')}${btn('예시 결과 보기','run-grade','primary','spark')}</div>`)}
function checkSimilar(){showModal(`<span class="badge">최종 답 확인</span><h2 style="margin-top:16px">어떤 답이 나왔나요?</h2><p class="subtitle">손글씨 자동 인식 대신, 작성한 최종 답을 입력해주세요.</p><label class="answer-field">나의 답<input id="similar-answer" inputmode="decimal" placeholder="숫자 입력" autocomplete="off"></label><p class="muted" id="answer-message">입력한 답을 이 문제의 정답과 비교해요.</p><div class="modal-actions">${btn('다시 풀기','close-modal','secondary')}${btn('확인하기','submit-similar','primary','check')}</div>`);$('#similar-answer').focus()}
document.addEventListener('click',async e=>{const el=e.target.closest('button');if(!el)return;if(el.dataset.go){go(el.dataset.go);return}if(el.dataset.open){const doc=el.dataset.open===demo.id?demo:state.documents.find(d=>d.id===el.dataset.open);if(doc)loadDoc(doc);return}if(el.dataset.filter){state.filter=el.dataset.filter;go('notebook');return}if(el.dataset.color){state.color=el.dataset.color;state.tool='pen';document.querySelectorAll('.color-button').forEach(b=>b.classList.toggle('active',b===el));updateTools();return}const a=el.dataset.action;if(!a)return;if(screens[a]){go(a);return}switch(a){case'choose-file':$('#pdf-input').click();break;case'open-demo':loadDoc(demo);break;case'start-editor':loadDoc(state.doc||demo);break;case'return-editor':state.pdf?go('editor'):loadDoc(demo);break;case'prev-page':case'next-page':state.page=Math.max(1,Math.min(state.pdf.numPages,state.page+(a==='next-page'?1:-1)));redo=[];go('editor');break;case'switch-mode':loadDoc(state.doc,state.mode==='exam'?'questions':'exam');break;case'tool-pen':case'tool-eraser':case'tool-hand':state.tool=a.replace('tool-','');updateTools();break;case'undo':{const stack=undoStacks[inkKey()]||[];if(stack.length){redo.push(structuredClone(currentInk()));state.ink[inkKey()]=stack.pop();saveInk();redrawInk()}else toast('취소할 필기가 없어요.');break}case'redo':if(redo.length){pushUndo(structuredClone(currentInk()));state.ink[inkKey()]=redo.pop();saveInk();redrawInk()}break;case'export':exportPDF();break;case'grade':grade();break;case'close-modal':closeModal();break;case'run-grade':closeModal();showModal('<div class="loading" style="min-height:220px"><span class="spinner"></span>예시 채점 결과를 준비하고 있어요.</div>');setTimeout(()=>{state.graded=true;store('ng-graded',true);closeModal();go('result')},900);break;case'all-filter':state.filter='all';go('notebook');break;case'review-original':loadDoc(demo,'questions',5);break;case'start-similar':state.mode='similar';state.zoom=1;redo=[];go('editor');break;case'check-similar':checkSimilar();break;case'submit-similar':{const value=$('#similar-answer').value.trim();if(!value){$('#answer-message').textContent='최종 답을 먼저 입력해주세요.';break}if(Number(value)===5){state.reviewed=true;store('ng-reviewed',true);closeModal();go('review-done')}else{$('#answer-message').innerHTML='<span class="wrong">아직 정답과 달라요.</span><br>원시함수 x³ − x² + x에 2와 1을 각각 대입한 뒤 빼보세요.'}break}}});
function updateTools(){document.querySelectorAll('[data-action^="tool-"]').forEach(b=>b.classList.toggle('active',b.dataset.action==='tool-'+state.tool));const c=$('#ink');if(c){c.style.pointerEvents=state.tool==='hand'?'none':'auto';c.style.cursor=state.tool==='eraser'?'cell':'crosshair'}}
document.addEventListener('change',e=>{if(e.target.id==='pen-width')state.width=Number(e.target.value);if(e.target.id==='zoom'){state.zoom=Number(e.target.value);drawPage()}if(e.target.id==='page-select'){state.page=Number(e.target.value);redo=[];go('editor')}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='Enter'&&$('#similar-answer')===document.activeElement)$('[data-action="submit-similar"]').click();if(state.route==='editor'&&(e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='z'){e.preventDefault();$(`[data-action="${e.shiftKey?'redo':'undo'}"]`)?.click()}});
let resizeTimer;window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(()=>{if(state.route==='editor')drawPage()},220)});
try{db=await initDB();state.documents=await dbAll()}catch{console.warn('Browser storage unavailable')}
go('home');
